import 'dart:convert';
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import '../models/models.dart';
import '../models/currency.dart';
class DatabaseService {
 static final DatabaseService instance=DatabaseService._(); DatabaseService._(); Database? _db;
 Future<Database> get db async { if(_db!=null)return _db!; _db=await openDatabase(join(await getDatabasesPath(),'daftar_alhisabat.db'),version:1,onConfigure:(d)async=>d.execute('PRAGMA foreign_keys = ON'),onCreate:(d,v)async{await d.execute('CREATE TABLE currencies(code TEXT PRIMARY KEY,name_ar TEXT,name_en TEXT,symbol TEXT,decimal_digits INTEGER,is_active INTEGER NOT NULL DEFAULT 1)'); for(final c in CurrencyCatalog.all){await d.insert('currencies',{'code':c.code,'name_ar':c.nameAr,'name_en':c.nameEn,'symbol':c.symbol,'decimal_digits':c.decimalDigits});} await d.execute('CREATE TABLE ledgers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,currency_code TEXT NOT NULL REFERENCES currencies(code),is_closed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL)'); await d.execute('CREATE TABLE persons(id INTEGER PRIMARY KEY AUTOINCREMENT,ledger_id INTEGER NOT NULL REFERENCES ledgers(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT,address TEXT,notes TEXT,kind TEXT NOT NULL DEFAULT "person",photo_path TEXT)'); await d.execute('CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,ledger_id INTEGER NOT NULL REFERENCES ledgers(id) ON DELETE CASCADE,person_id INTEGER NOT NULL REFERENCES persons(id) ON DELETE CASCADE,type TEXT NOT NULL,amount REAL NOT NULL CHECK(amount>0),date TEXT NOT NULL,description TEXT,notes TEXT,category TEXT,created_at TEXT NOT NULL)'); await d.execute('CREATE INDEX idx_tx_person_date ON transactions(person_id,date)'); await d.execute('CREATE INDEX idx_person_ledger ON persons(ledger_id)'); await d.execute('CREATE TABLE attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,transaction_id INTEGER REFERENCES transactions(id) ON DELETE CASCADE,path TEXT NOT NULL)'); await d.execute('CREATE TABLE reminders(id INTEGER PRIMARY KEY AUTOINCREMENT,person_id INTEGER REFERENCES persons(id) ON DELETE CASCADE,amount REAL NOT NULL,due_date TEXT NOT NULL,note TEXT,enabled INTEGER NOT NULL DEFAULT 1)'); await d.execute('CREATE TABLE account_closures(id INTEGER PRIMARY KEY AUTOINCREMENT,person_id INTEGER NOT NULL REFERENCES persons(id),closed_at TEXT NOT NULL,balance REAL NOT NULL)'); await d.execute('CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL)'); await d.execute('CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL)'); await d.insert('ledgers',{'name':'دفتر الشخصي','currency_code':'YER','created_at':DateTime.now().toIso8601String()});}}); return _db!; }
 Future<List<Ledger>> ledgers() async=>(await db).query('ledgers',where:'is_closed=0',orderBy:'id').then((r)=>r.map(Ledger.fromMap).toList());
 Future<int> addLedger(Ledger x) async=>(await db).insert('ledgers',x.toMap()..remove('id')..['created_at']=DateTime.now().toIso8601String());
 Future<List<Person>> persons(int ledgerId,{String query=''}) async{final r=await (await db).query('persons',where:'ledger_id=? AND (name LIKE ? OR phone LIKE ?)',whereArgs:[ledgerId,'%$query%','%$query%'],orderBy:'name');return r.map(Person.fromMap).toList();}
 Future<int> addPerson(Person x) async=>(await db).insert('persons',x.toMap()..remove('id'));
 Future<void> updatePerson(Person x) async=>(await db).update('persons',x.toMap(),where:'id=?',whereArgs:[x.id]);
 Future<void> deletePerson(int id) async=>(await db).delete('persons',where:'id=?',whereArgs:[id]);
 Future<List<TransactionItem>> transactions(int ledgerId,{int? personId,String query=''}) async{String w='ledger_id=?';final a=<Object?>[ledgerId];if(personId!=null){w+=' AND person_id=?';a.add(personId);}if(query.isNotEmpty){w+=' AND (description LIKE ? OR category LIKE ? OR date LIKE ? OR CAST(amount AS TEXT) LIKE ?)';a.addAll(['%$query%','%$query%','%$query%','%$query%']);}final r=await (await db).query('transactions',where:w,whereArgs:a,orderBy:'date DESC,id DESC');return r.map(TransactionItem.fromMap).toList();}
 Future<int> addTransaction(TransactionItem x) async=>(await db).insert('transactions',x.toMap()..remove('id')..['created_at']=DateTime.now().toIso8601String());
 Future<void> updateTransaction(TransactionItem x) async=>(await db).update('transactions',x.toMap(),where:'id=?',whereArgs:[x.id]);
 Future<void> deleteTransaction(int id) async=>(await db).delete('transactions',where:'id=?',whereArgs:[id]);
 Future<Map<String,double>> totals(int ledgerId,{int? personId}) async{final tx=await transactions(ledgerId,personId:personId);double r=0,p=0;for(final x in tx){if(x.type=='receivable'||x.type=='received')r+=x.amount;else p+=x.amount;}return {'receivable':r,'payable':p,'net':r-p};}
 Future<String> exportJson() async{final d=await db;final out=<String,dynamic>{};for(final table in ['ledgers','persons','transactions','reminders','account_closures','app_settings'])out[table]=await d.query(table);return jsonEncode({'version':1,'created_at':DateTime.now().toIso8601String(),'data':out});}
 Future<void> clearAll() async{final d=await db;for(final t in ['transactions','persons','ledgers','reminders','account_closures','audit_log'])await d.delete(t);await d.insert('ledgers',{'name':'دفتر الشخصي','currency_code':'YER','created_at':DateTime.now().toIso8601String()});}
}
